import {INPUT_PORTS,inputPorts,modelAssetCatalog,defaultIOBindings,outputFields} from '../shared/model-contracts.js';
import {escapeModelText as esc} from '../shared/model-result-view.js';
export function workingBindings(state,goal,draft){return draft.ioBindings||defaultIOBindings(state,goal,draft,{history:!draft.methodId||draft.code.includes('costHistory')});}
export function pipelineMarkup(state,goal,draft){const io=workingBindings(state,goal,draft);return `<nav class="builder-pipeline" aria-label="模型构建流程"><button data-studio-tab="data"><span>01 · 输入</span><strong>${Object.keys(io.inputs).length} 个数据资产</strong><small>版本 · 字段 · 主键</small></button><i>→</i><button data-studio-tab="algorithm"><span>02 · 算法</span><strong>${esc(goal.name)}</strong><small>方法 · 参数 · 工作副本</small></button><i>→</i><button data-studio-tab="output"><span>03 · 输出</span><strong>${esc(io.output.name)}</strong><small>${io.output.fields.length} 个字段 · ${io.output.grain==='enterprise-month-run'?'企业 / 月份 / 运行':'企业 / 运行'}</small></button><i>→</i><button data-studio-tab="use"><span>04 · 验证</span><strong>模拟与契约检查</strong><small>通过后发布模型包</small></button></nav>`;}
export function inputBindingMarkup(state,goal,draft,scopeMarkup){const assets=modelAssetCatalog(state),io=workingBindings(state,goal,draft);return `<section class="studio-panel builder-intro"><h2>绑定模型输入</h2><p>为每个输入端口选择数据资产版本，将资产字段映射到算法参数。绑定会随模型版本固定保存。</p></section><div class="builder-inputs">${inputPorts(goal.type,draft.methodId).map(id=>{const port=INPUT_PORTS[id],binding=io.inputs[id],asset=assets.find(a=>a.ref===binding?.assetRef),choices=assets.filter(a=>a.member===port.member&&(id==='history'||a.dataKey===draft.dataKey||a.sourceDigest===state.datasets[draft.dataKey]?.digest));return `<section class="studio-panel builder-port"><header><div><span class="builder-port-name">input.${id}</span><h2>${port.name}</h2></div><span class="studio-badge ${asset?'success':''}">${asset?'已选择资产':id==='history'?'可选历史输入':'待绑定'}</span></header><label class="studio-field"><span>数据资产与版本</span><select data-input-asset="${id}">${id==='history'?'<option value="">不附加历史资产</option>':''}${choices.map(a=>`<option value="${esc(a.ref)}" ${a.ref===binding?.assetRef?'selected':''}>${esc(a.name)} · ${esc(a.version)}</option>`).join('')}</select></label>${asset?`${['ledger','peers'].includes(id)?`<p>${id==='ledger'?'重定价首次生效日、周期和计息天数从原借据提取；下一重定价日按源周期计算。':'当前原台账未提供信用评级，算法会显示板块均值兜底依据。'}</p><button class="studio-text-button" data-studio-action="open-input-asset" data-id="${asset.id}">查看数据资产完整明细与来源</button>`:''}<div class="builder-asset-meta"><span>${asset.rows.length} 条记录</span><span>截至 ${esc(asset.asOf)}</span><span>${(/SIMULAT|SYNTHETIC/.test(asset.classification||''))?'演示数据':'已登记快照'}</span></div><details data-builder-detail="${id}:fields"><summary>字段映射与类型约束</summary><div class="studio-table-scroll"><table><thead><tr><th>算法输入字段</th><th>资产来源字段</th><th>类型 / 单位</th></tr></thead><tbody>${port.fields.map(field=>`<tr><td><b>${esc(field.label)}</b><small>${esc(field.key)}</small></td><td><select data-input-field="${id}" data-target-field="${field.key}">${asset.fields.map(source=>`<option value="${source.key}" ${binding.fields[field.key]===source.key?'selected':''}>${esc(source.label||source.key)} · ${source.key}</option>`).join('')}</select></td><td>${field.type}${field.nullable?' · 可为空（保留缺失）':''}${field.unit?' · '+field.unit:''}</td></tr>`).join('')}</tbody></table></div></details><details data-builder-detail="${id}:sample"><summary>资产结构与小样本</summary><p>资产 ${esc(asset.id)} · 版本 ${esc(asset.version)}</p><p class="studio-code-ref">指纹 ${esc(asset.digest)}</p><pre>${esc(JSON.stringify(asset.rows.slice(0,2),null,2))}</pre></details>`:'<p>可在算法中使用合同口径回溯；若要训练趋势，请选择明确的历史资产。</p>'}</section>`;}).join('')}</div><section class="studio-panel"><details data-builder-detail="input-filter"><summary>输入记录过滤 · ${draft.objectIds.length} 个企业主键</summary><p>这是模型适用范围，模拟时可以从中选取少量样本。</p>${scopeMarkup}</details><footer class="studio-panel-footer"><button class="studio-button primary" data-studio-action="save-input-bindings">保存输入绑定</button><button class="studio-button" data-studio-action="save-to-model">保存并构建算法</button></footer></section>`;}
export function outputBindingMarkup(state,goal,draft){const io=workingBindings(state,goal,draft),output=io.output,series=Boolean(draft.methodId),destinations=goal.type==='cost'&&series?[['temporal','时序分析'],['objects','对象分析']]:goal.type==='risk'?[['objects','对象分析'],['events','模型监控提示']]:[['objects','对象分析']];return `<section class="studio-panel"><header><div><h2>约定输出数据集</h2><p>声明输出字段、粒度和使用位置。模拟只生成调试快照；业务运行才形成带运行编号的结果数据集。</p></div><span class="studio-badge">输出契约</span></header><div class="builder-output-fields"><label class="studio-field"><span>输出数据集名称</span><input id="output-name" value="${esc(output.name)}" required></label><label class="studio-field"><span>稳定数据集标识</span><input id="output-id" value="${esc(output.datasetId)}" required></label></div><p>主键粒度：${series?'企业 × 月份 × 运行编号':'企业 × 运行编号'}。同一个运行不得输出重复主键。</p><div class="studio-table-scroll"><table><thead><tr><th>算法输出</th><th>落入数据集的字段名</th><th>类型</th><th>单位</th></tr></thead><tbody>${output.fields.map((field,index)=>`<tr><td><strong>${esc(field.label)}</strong><small>${esc(field.source)}</small></td><td><input data-output-field="${index}" value="${esc(field.name)}" aria-label="${esc(field.label)}输出字段名"></td><td>${field.type}</td><td>${esc(field.unit||'—')}</td></tr>`).join('')}</tbody></table></div><h3>允许的使用位置</h3><div class="builder-destinations">${destinations.map(([id,label])=>`<label><input data-output-destination="${id}" type="checkbox" ${output.destinations.includes(id)?'checked':''}> ${label}</label>`).join('')}</div><p>输出记录引用模型版本、输入资产指纹和本次实参，历史结果不会随新版本覆盖。</p><footer class="studio-panel-footer"><button class="studio-button" data-studio-action="reset-output-bindings">恢复推荐契约</button><button class="studio-button primary" data-studio-action="save-output-bindings">保存输出约定</button></footer></section>`;}
export function simulationSummary(run){if(!run)return '<div class="builder-empty">尚未运行。选择输入样本，先模拟，再执行完整契约核验。</div>';if(run.status!=='SUCCEEDED')return `<p class="studio-notice ${run.status==='FAILED'?'error':''}" role="status">${esc(run.error||'模拟未完成')}</p>`;const emission=run.emittedOutput;return `<section class="builder-simulation-result"><header><h3>${run.purpose==='SIMULATION'?'开发模拟完成':run.purpose==='VALIDATION'?'契约核验通过':'固定运行引用'}</h3><span class="studio-badge success">${run.checks.length} 项检查通过</span></header><div class="builder-test-stats"><div><span>输入样本</span><strong>${run.objectIds.length}</strong></div><div><span>输出记录</span><strong>${emission?.rowCount??run.output.rows.length}</strong></div><div><span>数据集</span><b>${esc(emission?.name||'继承结果结构')}</b></div></div><ul class="studio-checks">${run.checks.map(check=>`<li>✓ ${esc(check.label)}</li>`).join('')}</ul><p>这里用于构建和验证模型。企业业务结果在已绑定的对象分析或时序视图中查看。</p><details class="builder-debug-sample" data-builder-detail="debug-output"><summary>调试输出样例 · 仅1条</summary><pre>${esc(JSON.stringify(emission?.rows[0]||run.output.rows[0],null,2))}</pre></details><details><summary>运行及绑定依据</summary><p>${esc(run.id)} · ${esc(run.versionName||'工作草稿')} · ${esc(run.at)}</p><pre>${esc(JSON.stringify({inputs:run.inputLineage||[],output:run.ioBindings?.output||null,parameters:run.parameters,signature:run.signature},null,2))}</pre></details></section>`;}
